SELECT song.*, source.source_type, source.location, source.username, source.password_encrypted, remote.song_id AS remote_resource_id, remote.identity_size, remote.identity_modified, remote.etag AS content_etag FROM media_song song JOIN media_source source ON source.id = song.source_id LEFT JOIN webdav_resource remote ON remote.song_id = song.id AND remote.archived_at IS NULL WHERE song.id = @{id}
